constexpr char numero = 'n';
constexpr char nombre = 'v';
constexpr char declaracion = 'd';
constexpr char constante = 'c';
constexpr char final_texto = 'f';

struct Token {
    char clase;
    int valor;
    std::string texto;
};

bool es_letra(char c) {
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

bool es_digito(char c) {
    return c >= '0' && c <= '9';
}

bool sigue_nombre(char c) {
    return es_letra(c) || es_digito(c) || c == '_';
}

bool nombre_valido(const std::string& texto) {
    if (texto.empty() || texto.size() > 12 || !es_letra(texto[0])) {
        return false;
    }
    for (char c : texto) {
        if (!sigue_nombre(c)) return false;
    }
    return texto != "crea" && texto != "fija";
}

Token palabra_token(const std::string& palabra) {
    if (palabra == "crea") return Token{declaracion, 0, ""};
    if (palabra == "fija") return Token{constante, 0, ""};
    return Token{nombre, 0, palabra};
}

Token leer_token(std::istringstream& entrada) {
    char actual = '?';
    while (entrada.get(actual)) {
        if (actual == ' ' || actual == '\t' || actual == '\n') continue;
        if (es_digito(actual)) {
            int valor = actual - '0';
            while (entrada.get(actual)) {
                if (es_digito(actual)) {
                    valor = valor * 10 + (actual - '0');
                    if (valor > 99) throw std::runtime_error("Numero fuera de dominio");
                } else {
                    entrada.putback(actual);
                    if (!entrada) throw std::runtime_error("No se pudo conservar el caracter");
                    return Token{numero, valor, ""};
                }
            }
            if (entrada.bad() || !entrada.eof()) throw std::runtime_error("Fallo del flujo");
            return Token{numero, valor, ""};
        }
        if (es_letra(actual)) {
            std::string palabra(1, actual);
            while (entrada.get(actual)) {
                if (sigue_nombre(actual)) {
                    palabra += actual;
                    if (palabra.size() > 12) throw std::runtime_error("Nombre demasiado largo");
                } else {
                    entrada.putback(actual);
                    if (!entrada) throw std::runtime_error("No se pudo conservar el caracter");
                    return palabra_token(palabra);
                }
            }
            if (entrada.bad() || !entrada.eof()) throw std::runtime_error("Fallo del flujo");
            return palabra_token(palabra);
        }
        if (actual == '+' || actual == '-' || actual == '*' || actual == '/'
                || actual == '%' || actual == '(' || actual == ')'
                || actual == ';' || actual == '=') {
            return Token{actual, 0, ""};
        }
        throw std::runtime_error("Caracter no admitido");
    }
    if (entrada.bad() || !entrada.eof()) throw std::runtime_error("Fallo del flujo");
    return Token{final_texto, 0, ""};
}

bool token_valido(const Token& token) {
    if (token.clase == numero) {
        return token.valor >= 0 && token.valor <= 99 && token.texto.empty();
    }
    if (token.clase == nombre) {
        return token.valor == 0 && nombre_valido(token.texto);
    }
    const bool signo = token.clase == '+' || token.clase == '-' || token.clase == '*'
        || token.clase == '/' || token.clase == '%' || token.clase == '('
        || token.clase == ')' || token.clase == ';' || token.clase == '=';
    return token.valor == 0 && token.texto.empty()
        && (signo || token.clase == declaracion || token.clase == constante || token.clase == final_texto);
}

class Lector_tokens {
public:
    explicit Lector_tokens(const std::string& texto) : entrada_{texto} {
        if (texto.size() > 120) throw std::runtime_error("Texto demasiado largo");
    }

    Token leer() {
        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(const Token& token) {
        if (lleno_) throw std::runtime_error("Buffer ocupado");
        if (!token_valido(token)) throw std::runtime_error("Token invalido");
        guardado_ = token;
        lleno_ = true;
    }

    bool descartar_operacion() {
        if (entrada_.bad()) throw std::runtime_error("Fallo grave del flujo");
        if (lleno_) {
            const Token pendiente = guardado_;
            lleno_ = false;
            if (pendiente.clase == ';') return true;
            if (pendiente.clase == final_texto) return false;
        }
        entrada_.clear();
        char c = '?';
        while (entrada_.get(c)) {
            if (c == ';') return true;
        }
        if (entrada_.bad() || !entrada_.eof()) throw std::runtime_error("Fallo del flujo");
        return false;
    }

private:
    std::istringstream entrada_;
    bool lleno_ = false;
    Token guardado_{final_texto, 0, ""};
};

int resultado_en_dominio(int candidato) {
    if (candidato < -100 || candidato > 100) {
        throw std::runtime_error("Resultado fuera de dominio");
    }
    return candidato;
}

struct Vinculo {
    std::string nombre;
    int valor;
    bool modificable;
};

class Tabla_nombres {
public:
    bool contiene(const std::string& nombre_buscado) const {
        for (const Vinculo& dato : datos_) {
            if (dato.nombre == nombre_buscado) return true;
        }
        return false;
    }

    int consultar(const std::string& nombre_buscado) const {
        for (const Vinculo& dato : datos_) {
            if (dato.nombre == nombre_buscado) return dato.valor;
        }
        throw std::runtime_error("Nombre no definido");
    }

    void definir(const std::string& nuevo, int valor, bool modificable) {
        if (!nombre_valido(nuevo)) throw std::runtime_error("Nombre invalido");
        resultado_en_dominio(valor);
        if (contiene(nuevo)) throw std::runtime_error("Nombre ya definido");
        if (datos_.size() >= 8) throw std::runtime_error("Tabla llena");
        datos_.push_back(Vinculo{nuevo, valor, modificable});
    }

    void asignar(const std::string& existente, int valor) {
        resultado_en_dominio(valor);
        for (Vinculo& dato : datos_) {
            if (dato.nombre == existente) {
                if (!dato.modificable) throw std::runtime_error("Nombre constante");
                dato.valor = valor;
                return;
            }
        }
        throw std::runtime_error("Nombre no definido");
    }

    const std::vector<Vinculo>& entradas() const {
        return datos_;
    }

private:
    std::vector<Vinculo> datos_;
};

int leer_expresion(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad);

int leer_unidad(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad) {
    if (profundidad > 8) throw std::runtime_error("Profundidad excedida");
    const Token token = lector.leer();
    if (token.clase == numero) return token.valor;
    if (token.clase == nombre) return tabla.consultar(token.texto);
    if (token.clase == '+') return leer_unidad(lector, tabla, profundidad + 1);
    if (token.clase == '-') {
        const int valor = leer_unidad(lector, tabla, profundidad + 1);
        return resultado_en_dominio(-valor);
    }
    if (token.clase == '(') {
        const int valor = leer_expresion(lector, tabla, profundidad + 1);
        const Token cierre = lector.leer();
        if (cierre.clase != ')') {
            lector.devolver(cierre);
            throw std::runtime_error("Se esperaba )");
        }
        return valor;
    }
    lector.devolver(token);
    throw std::runtime_error("Se esperaba una unidad");
}

int continuar_termino(int izquierda, Lector_tokens& lector,
        const Tabla_nombres& tabla, int profundidad) {
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '*' || token.clase == '/' || token.clase == '%') {
            const int derecha = leer_unidad(lector, tabla, profundidad);
            if ((token.clase == '/' || token.clase == '%') && derecha == 0) {
                throw std::runtime_error("Divisor cero");
            }
            if (token.clase == '*') izquierda = resultado_en_dominio(izquierda * derecha);
            else if (token.clase == '/') izquierda = resultado_en_dominio(izquierda / derecha);
            else izquierda = resultado_en_dominio(izquierda % derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_termino(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad) {
    return continuar_termino(leer_unidad(lector, tabla, profundidad), lector, tabla, profundidad);
}

int continuar_expresion(int izquierda, Lector_tokens& lector,
        const Tabla_nombres& tabla, int profundidad) {
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '+' || token.clase == '-') {
            const int derecha = leer_termino(lector, tabla, profundidad);
            if (token.clase == '+') izquierda = resultado_en_dominio(izquierda + derecha);
            else izquierda = resultado_en_dominio(izquierda - derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_expresion(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad) {
    return continuar_expresion(leer_termino(lector, tabla, profundidad), lector, tabla, profundidad);
}

int leer_definicion(Lector_tokens& lector, Tabla_nombres& candidata, bool modificable) {
    const Token destino = lector.leer();
    if (destino.clase != nombre) {
        lector.devolver(destino);
        throw std::runtime_error("Se esperaba un nombre");
    }
    const Token igual = lector.leer();
    if (igual.clase != '=') {
        lector.devolver(igual);
        throw std::runtime_error("Se esperaba =");
    }
    const int valor = leer_expresion(lector, candidata, 0);
    candidata.definir(destino.texto, valor, modificable);
    return valor;
}

int leer_sentencia(Lector_tokens& lector, Tabla_nombres& candidata) {
    const Token primero = lector.leer();
    if (primero.clase == declaracion) {
        return leer_definicion(lector, candidata, true);
    }
    if (primero.clase == constante) {
        return leer_definicion(lector, candidata, false);
    }
    if (primero.clase == nombre) {
        const Token siguiente = lector.leer();
        if (siguiente.clase == '=') {
            const int valor = leer_expresion(lector, candidata, 0);
            candidata.asignar(primero.texto, valor);
            return valor;
        }
        lector.devolver(siguiente);
        const int inicial = candidata.consultar(primero.texto);
        const int termino = continuar_termino(inicial, lector, candidata, 0);
        return continuar_expresion(termino, lector, candidata, 0);
    }
    lector.devolver(primero);
    return leer_expresion(lector, candidata, 0);
}

int leer_operacion(Lector_tokens& lector, Tabla_nombres& tabla) {
    Tabla_nombres candidata = tabla;
    const int valor = leer_sentencia(lector, candidata);
    const Token fin = lector.leer();
    if (fin.clase != ';') {
        lector.devolver(fin);
        throw std::runtime_error("Se esperaba ;");
    }
    tabla = candidata;
    return valor;
}

