        if (lleno_) {
            lleno_ = false;
            return guardado_;
        }
        return leer_token(entrada_);
    }

    void devolver(const Token& token) {
        if (lleno_) throw std::runtime_error("Buffer ocupado");
        if (!token_valido(token)) throw std::runtime_error("Token invalido");
        guardado_ = token;
        lleno_ = true;
    }

    bool descartar_operacion() {
        if (entrada_.bad()) throw std::runtime_error("Fallo grave del flujo");
        if (lleno_) {
            const Token pendiente = guardado_;
            lleno_ = false;
            if (pendiente.clase == ';') return true;
            if (pendiente.clase == final_texto) return false;
        }
        entrada_.clear();
        char c = '?';
        while (entrada_.get(c)) {
            if (c == ';') return true;
        }
        if (entrada_.bad() || !entrada_.eof()) throw std::runtime_error("Fallo del flujo");
        return false;
    }

private:
