    const int valor = leer_sentencia(lector, candidata);
    const Token fin = lector.leer();
    if (fin.clase != ';') {
        lector.devolver(fin);
        throw std::runtime_error("Se esperaba ;");
    }
    tabla = candidata;
    return valor;
}

void probar(const std::string& texto) {
    Lector_tokens lector{texto};
    Tabla_nombres tabla;
    tabla.definir("unidad", 1, false);
    tabla.definir("limite", 100, false);
    std::vector<int> historial;
    int aceptadas = 0;
    int rechazadas = 0;
    while (true) {
        try {
            const Token inicio = lector.leer();
            if (inicio.clase == final_texto) break;
            lector.devolver(inicio);
            const int valor = leer_operacion(lector, tabla);
            historial.push_back(valor);
            ++aceptadas;
            std::cout << "Valor: " << valor << "\n";
        } catch (const std::runtime_error& error) {
            ++rechazadas;
            std::cout << "Error: " << error.what() << "\n";
            if (!lector.descartar_operacion()) break;
        }
    }
    std::cout << "Aceptadas: " << aceptadas << "\nRechazadas: " << rechazadas << "\n";
    std::cout << "Tabla:";
    for (const Vinculo& dato : tabla.entradas()) {
        std::cout << ' ' << dato.nombre << '=' << dato.valor;
        std::cout << (dato.modificable ? "(V)" : "(C)");
    }
    std::cout << "\n";
    int suma = 0;
    for (int valor : historial) suma += valor;
    std::cout << "Historial:";
    for (int valor : historial) std::cout << ' ' << valor;
    std::cout << "\nSuma: " << suma << "\n";
    int mutables = 0;
    int constantes = 0;
    for (const Vinculo& dato : tabla.entradas()) {
        if (dato.modificable) ++mutables;
        else ++constantes;
    }
    std::cout << "Mutables: " << mutables << "\nConstantes: " << constantes << "\n";
    int ceros = 0;
    for (const Vinculo& dato : tabla.entradas()) {
        if (dato.valor == 0) ++ceros;
    }
    std::cout << "Ceros: " << ceros << "\n";
}

int main() {
    std::cout << "Caso 1\n";
    probar("crea a=0;");
    std::cout << "Caso 2\n";
    probar("crea a=0;a=1;");
    std::cout << "Caso 3\n";
    probar("fija k=unidad;k=0;");
    std::cout << "Caso 4\n";
    probar("crea a=0;fija b=0;a=2;");
    return 0;
}
